import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';

const JobSeekerDashboard: React.FC = () => {
    const navigate = useNavigate();
    const [agencyDetails, setAgencyDetails] = useState<any>(null);
    const [associatedJobSeekers, setAssociatedJobSeekers] = useState<any>(null);
    const [status, setStatus] = useState<string>('pending'); // Initialize status

    useEffect(() => {
        const token = localStorage.getItem('token');
        const agency = localStorage.getItem('agencyDetails');
        const associatedJobSeekers = localStorage.getItem('associatedJobSeekers'); 

        if (!token) {
            navigate('/login'); 
        }

        if (agency) {
            const parsedAgency = JSON.parse(agency);
            setAgencyDetails(parsedAgency);
        }

        if (associatedJobSeekers) {
            const parsedJobSeeker = JSON.parse(associatedJobSeekers);
            setAssociatedJobSeekers(parsedJobSeeker);
            setStatus(parsedJobSeeker.status); // Fetch initial status
        }

        // Polling for status updates every 5 seconds
        const interval = setInterval(() => {
            fetchJobSeekerStatus(parsedJobSeeker.id);
        }, 5000);

        return () => clearInterval(interval); // Cleanup on unmount
    }, [navigate]);

    const fetchJobSeekerStatus = async (userId) => {
        try {
            const response = await fetch(`http://localhost:8080/api/jobseeker/${userId}`);
            const data = await response.json();
            if (data.status) {
                setStatus(data.status);
            }
        } catch (error) {
            console.error('Error fetching job seeker status', error);
        }
    };

    const handleChatClick = () => {
        navigate('/chat-room');
    };

    return (
        <div className="container mt-5">
            <h1 className="text-center">Job Seeker Dashboard</h1>
            {associatedJobSeekers && (
                <div className="alert alert-info">
                    <h4>Welcome, {associatedJobSeekers.firstName} {associatedJobSeekers.lastName}!</h4>
                </div>
            )}
            <div className="card p-4 mt-3">
                <h2>Your Agency Details</h2>
                {agencyDetails ? (
                    <div>
                        <p><strong>Agency Name:</strong> {agencyDetails.firstName} {agencyDetails.lastName}</p>
                        <p><strong>Email:</strong> {agencyDetails.email}</p>
                        <p><strong>Phone:</strong> {agencyDetails.phone}</p>
                        {status === 'confirmed' ? (
                            <>
                                <button onClick={handleChatClick} className="btn btn-primary mt-3">
                                    Start Chat
                                </button>
                                <div className="alert alert-success mt-3">
                                    You have been confirmed by your agency. You can start chatting now!
                                </div>
                            </>
                        ) : (
                            <p className="text-danger mt-3">Your agency has not confirmed you for chat.</p>
                        )}
                    </div>
                ) : (
                    <p>No agency associated with your profile.</p>
                )}
            </div>
        </div>
    );
};

export default JobSeekerDashboard;
